class Chalk::Semiring::ChalkIR :isa(Chalk::Semiring::Composite) {
    field $grammar :param :reader;
    field $builder :reader;

    BUILD {
        # Create IR Builder BEFORE creating child semirings
        $builder = Chalk::IR::Builder->new();

        # Create SPPF semiring for parse forest
        my $sppf_sr = Chalk::Semiring::SPPF->new();

        # Create Semantic semiring with IR builder in environment
        my $semantic_sr = Chalk::Semiring::Semantic->new(
            grammar => $grammar,
            env => { ir_builder => $builder }
        );

        # Pass semirings array to parent constructor via params
        # The parent's ADJUST block will handle identity element creation
        $self->_set_semirings([$sppf_sr, $semantic_sr]);
    }

    method _set_semirings($semirings_ref) {
        # Internal method to set the inherited semirings field
        # This works because fields are accessible through the object hash
        $self->{semirings} = $semirings_ref;
    }
}

